// CLX Business Signal Detection v2 — Parse Signal Response

const response = $input.item.json;
const lead = $('Split In Batches').first().json;

let rawText = '';
if (response && response.content && Array.isArray(response.content)) {
  rawText = response.content.map(c => c.text || '').join('');
} else if (response && typeof response.content === 'string') {
  rawText = response.content;
}
rawText = rawText.replace(/```json\s*/gi, '').replace(/```\s*/gi, '').trim();

let signal;
if (!rawText || rawText.trim() === '') {
  // A missing model response is not a buying signal. Persisting one as
  // 'Manual review needed' put parser output in front of customers as
  // intent -- 284 of 847 signalled leads carried exactly that.
  signal = {
    detected_signal: null,
    growth_stage: 'Established',
    recommended_campaign_type: 'general_outreach',
    signal_confidence: 'Unavailable',
    outreach_timing: 'This Month',
    _signal_error: 'empty_model_response'
  };
} else {
  try {
    signal = JSON.parse(rawText);
  } catch (e) {
    // Same rule for malformed JSON. The error is preserved for triage in
    // _signal_error, never in the customer-facing field.
    signal = {
      detected_signal: null,
      growth_stage: 'Established',
      recommended_campaign_type: 'general_outreach',
      signal_confidence: 'Unavailable',
      outreach_timing: 'This Month',
      _signal_error: 'parse_error: ' + String(e && e.message).slice(0, 200)
    };
  }
}

const now = new Date().toISOString();

return {
  json: {
    id: lead.id,
    // Explicit null, not a cheerful default. 'No signal detected' is a
    // finding; an absent one is an unknown, and the two must not read alike.
    detected_signal: signal.detected_signal || null,
    _signal_error: signal._signal_error || null,
    growth_stage: signal.growth_stage || 'Established',
    recommended_campaign_type: signal.recommended_campaign_type || 'general_outreach',
    signal_confidence: signal.signal_confidence || 'Low',
    outreach_timing: signal.outreach_timing || 'This Month',
    lead_status: 'Signal Detected',
    updated_at: now
  }
};

// CLX Business Signal Detection v2 — Prep Update Signal

const item = $input.item.json;

const body = {
  p_lead_id: item.id,
  p_fields: {
    detected_signal: item.detected_signal,
    growth_stage: item.growth_stage,
    recommended_campaign_type: item.recommended_campaign_type,
    signal_confidence: item.signal_confidence,
    outreach_timing: item.outreach_timing,
    // Only claim a signal was detected when one actually was. Marking a
    // failed parse as 'Signal Detected' is how the funnel counted 284
    // errors as buying intent.
    lead_status: item.detected_signal ? 'Signal Detected' : 'Scored'
  }
};

if (item._signal_error) {
  // leads has no signal_error column and update_lead uses an explicit
  // allowlist, so an extra key would be silently dropped. The execution
  // log is where this is actually visible.
  console.log('SIGNAL PARSE FAILURE:', JSON.stringify({ lead_id: item.id, error: item._signal_error }));
}

console.log('PREP UPDATE:', JSON.stringify({ lead_id: item.id, status: body.p_fields.lead_status, signal: item.detected_signal }));

return { json: { ...item, rpc_body: JSON.stringify(body) } };

// Build the signal prompt from the vertical's OWN definition of a signal.
//
// The prompt used to ask, of every lead in every industry, "what business
// signal is most relevant right now" -- with no statement of what counts as
// a signal, and no market data to check against. market_signals_processed
// has never held a row. So the model was asked to find something it had no
// way to find, and 60 of 79 leads ended up at lead_status 'Signal Detected'
// with detected_signal NULL.
//
// niche_overlays.behavior_config has held the answer all along: signal_types
// and intent_rules, seeded for all eight verticals, read by no workflow.
// Moving companies signal through fleet_expansion and hiring_movers;
// insurance brokers through advisor_recruitment and new_carrier_appointment.
// Those are different questions and were being asked as one.
//
// Prompt built in a Code node rather than an inline expression: it is
// multi-line, and a single unescaped newline inside an expression silently
// breaks the whole request. That exact fault cost this project a day on
// the research workflow.

const lead = $('Split In Batches').first().json;

let cfg = {};
try {
  const rows = $('Fetch Signal Definition').all().map(function (i) { return i.json; });
  let row = rows.length ? rows[0] : null;
  if (Array.isArray(row)) row = row[0];
  if (row && !row.code && !row.message) cfg = row;
} catch (e) { cfg = {}; }

const bc = cfg.behavior_config || {};
const signalTypes = Array.isArray(bc.signal_types) ? bc.signal_types : [];
const intentRules = bc.intent_rules || {};
const painSignals = Array.isArray(cfg.pain_signals) ? cfg.pain_signals : [];

const val = function (v) {
  const s = (v === null || v === undefined) ? '' : String(v).trim();
  return s || 'not provided';
};

const lines = [
  'You are a B2B sales intelligence analyst for the Crystallux Sales Engine.',
  '',
  'Lead:',
  'Company: ' + val(lead.company),
  'Industry: ' + val(lead.industry),
  'City: ' + val(lead.city),
  'Job Title: ' + val(lead.job_title),
  'Lead Score: ' + val(lead.lead_score),
  'Research: ' + val(lead.research_summary),
  'Likely need: ' + val(lead.likely_business_need)
];

if (signalTypes.length) {
  lines.push('', 'For this vertical (' + val(cfg.niche_name) + '), a buying signal',
             'is ONE OF these and nothing else:', '  ' + signalTypes.join(', '));
}
if (painSignals.length) {
  lines.push('', 'Known pain signals: ' + painSignals.join(', '));
}
if (intentRules.hot || intentRules.warm || intentRules.cold) {
  lines.push('', 'Intent rules:',
             '  hot:  ' + val(intentRules.hot),
             '  warm: ' + val(intentRules.warm),
             '  cold: ' + val(intentRules.cold));
}

lines.push('',
  'Return ONLY a raw JSON object, no markdown, with these fields:',
  '- detected_signal: the signal you can EVIDENCE from the research above,',
  '  named using the vocabulary given. If the research does not evidence one,',
  '  return null. Do not infer a signal from the industry alone.',
  '- growth_stage: one of Startup, Growing, Established, Enterprise',
  '- recommended_campaign_type: a short slug',
  '- signal_confidence: High, Medium or Low',
  '- outreach_timing: This Week, This Month or This Quarter',
  '',
  'null for detected_signal is a correct and expected answer. A lead with no',
  'evidenced signal is worth knowing about accurately; an invented one is',
  'worse than none, because the funnel then treats it as intent.');

const prompt = lines.join('\n');

return { json: {
  lead_id: lead.id,
  _has_definition: signalTypes.length > 0,
  _vertical: cfg.niche_name || null,
  signal_payload: {
    model: 'claude-haiku-4-5-20251001',
    max_tokens: 1024,
    messages: [{ role: 'user', content: prompt }]
  }
} };
